using System;using System.Threading;using System.Diagnostics;
sealed class BuffResult {public bool Started,Blocked;public string Message;}
static class BuffService {
 public static BuffResult Start(CharacterRef character){var result=new BuffResult();BuffBridge bridge=null;bool interrupted=false;try{using(var state=new CharacterMemory(character.Pid)){if(state.Id!=character.Id)throw new Exception("Personagem mudou; atualize a lista.");if(!state.BuffMacroConfigured())throw new Exception("Cadastre os buffs na macro 1 (segundo slot) da janela R.");interrupted=state.AnyMacroRunning();}if(interrupted)StopRunningMacro(character,result);bridge=new BuffBridge(character.Pid);if(bridge.CharacterId!=character.Id)throw new Exception("Personagem mudou antes do comando.");bridge.BuffOnce();if(bridge.LastResult!=1)throw new Exception("Cliente não aceitou o início da macro.");result.Started=true;result.Message=character.Name+(interrupted?": macro anterior interrompida; macro 1 acionada.":": macro 1 acionada uma vez.");}catch(Exception e){result.Message=character.Name+": "+e.Message;}finally{if(bridge!=null){try{bridge.Dispose();}catch(Exception e){result.Message+=" "+e.Message;}result.Blocked=!bridge.RestoreSucceeded;if(result.Blocked)result.Message+=" Ponte sem restauração confirmada; reinicie esse cliente.";}}return result;}
 public static bool MacroBusy(CharacterRef character){using(var state=new CharacterMemory(character.Pid)){if(state.Id!=character.Id)throw new Exception("Personagem mudou; atualize a lista.");return state.AnyMacroRunning();}}
 // Rebuff and "new command wins": the running macro (attack, previous buff or the player's own) is stopped before macro 1.
 static void StopRunningMacro(CharacterRef character,BuffResult result){AttackBridge bridge=null;try{bridge=new AttackBridge(character.Pid);if(bridge.CharacterId!=character.Id)throw new Exception("Personagem mudou antes do comando.");bridge.StopMacro(-1);}finally{if(bridge!=null){bridge.Dispose();if(!bridge.RestoreSucceeded){result.Blocked=true;throw new Exception("Ponte sem restauração confirmada; reinicie esse cliente.");}}}
  var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<1500){using(var state=new CharacterMemory(character.Pid))if(!state.AnyMacroRunning())return;Thread.Sleep(100);}throw new Exception("A macro em execução não parou; macro 1 não acionada.");}
 public static bool Running(CharacterRef character){using(var state=new CharacterMemory(character.Pid)){if(state.Id!=character.Id)return false;return state.BuffMacroRunning();}}
}
